/// <summary>
/// The <c>METPendingVendorInvoiceClaimCalculationsTaskHandler</c> class performs the workflow automated task for queuing an approved vendor invoice for posting.
/// </summary>
internal class METPendingVendorInvoiceClaimCalculationsTaskHandler implements WorkflowElementExecutionEventHandler, WorkflowElementExternalExecutionEventHandler
{
}

Method.Source:
/// <summary>
/// Implements the <c>execute</c> method of the <c>WorkflowElementExecutionEventHandler</c>.
/// </summary>
/// <param name="_workflowElementEventArgs">An instance of the <c>WorkflowElementEventArgs</c> class.</param>
public void execute(WorkflowElementEventArgs _workflowElementEventArgs)
{
    if (METVendParameters::find().EnableMetcashMatchingLogic)
    {
        #OCCRetryCount
        System.Exception netExcepn;

        WorkflowContext context = _workflowElementEventArgs.parmWorkflowContext();
        VendInvoiceInfoTable vendInvoiceInfoTable = VendInvoiceInfoTable::findRecId(context.parmRecId());

        if (!vendInvoiceInfoTable.isChargeThroughEnabled() && !vendInvoiceInfoTable.isLandedCostEnabled())
        {
            if (!(vendInvoiceInfoTable.RequestStatus == VendInvoiceRequestStatus::InReview || vendInvoiceInfoTable.RequestStatus == VendInvoiceRequestStatus::Approved))
            {
                throw error(strFmt("@SYS319867", vendInvoiceInfoTable.Num));
            }

            try
            {
                VendInvoiceInfoLine invoiceinfoLine;

                select firstonly RecId from invoiceinfoLine
                    where invoiceinfoLine.ParmId == vendInvoiceInfoTable.ParmId
                    && invoiceinfoLine.TableRefId == vendInvoiceInfoTable.TableRefId
                    && invoiceinfoLine.ReasonTableRef != 0;

                if (vendInvoiceInfoTable.METClaimInvoice == NoYes::No && invoiceinfoLine.RecId)
                {
                    METPendingVendorInvoiceClaimCalculations claimCalc = new METPendingVendorInvoiceClaimCalculations();
                    claimCalc.createClaimData(vendInvoiceInfoTable);
                }
            }
            catch (Exception::CLRError)
            {
                netExcepn = CLRInterop::getLastException();
                throw error(netExcepn.ToString());
            }
            catch (Exception::Deadlock)
            {
                retry;
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::UpdateConflictNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    throw Exception::UpdateConflict;
                }
            }
            catch
            {
                throw error("@MET:UnhandledError");
            }
        }
    }
}
